from abc import ABC, abstractmethod

class Processor(ABC):
    @abstractmethod
    def run(self, text: str) -> str:
        pass

class Upper:
    def run(self, text: str) -> str:
        return text.upper()

class Lower:
    def run(self, text: str) -> str:
        return text.lower()

for tool in [Upper(), Lower()]:
    print(tool.run("Py"))

